from PIL import Image
import numpy as np
im=np.array(Image.open('/app/target.png').convert('RGB'))
mask=(im.mean(axis=2)<60)
for v in [275,280,290,300,320,350,380,400,420,440,455,470,480,500,520,540,560,580,600,620,640,660,680,700,710,720]:
 x=np.where(mask[v])[0]
 runs=[]
 for u in x:
  if not runs or u>runs[-1][-1]+1:runs.append([int(u)])
  else:runs[-1].append(int(u))
 print(v,[(r[0],r[-1]) for r in runs])
